package com.smartdoc.ai.provider;
public class ModelRouter { private final AiProviderMapper providers; private final AiRoutingMapper routing; private final ProviderSecretVault vault; private final ProviderAdapterRegistry registry; public ModelRouter(AiProviderMapper p,AiRoutingMapper r,ProviderSecretVault v,ProviderAdapterRegistry a){providers=p;routing=r;vault=v;registry=a;}
 public boolean hasConfiguredDefault(long user,ProviderCapability capability){AiRoutingConfig r=routing.selectOwned(user);return r!=null&&(capability==ProviderCapability.TEXT?r.getDefaultTextProviderId()!=null:r.getDefaultVisionProviderId()!=null);}
 public AiRoutingConfig routingFor(long user){return routing.selectOwned(user);}
 public ProviderSession require(long user,ProviderCapability capability){AiRoutingConfig r=routing.selectOwned(user);Long id=r==null?null:(capability==ProviderCapability.TEXT?r.getDefaultTextProviderId():r.getDefaultVisionProviderId());if(id==null)throw new ProviderHttpException("MODEL_NOT_CONFIGURED",400);AiProviderConfig p=providers.selectOwnedEnabled(id,user);if(p==null||!p.supports(capability))throw new ProviderHttpException("MODEL_NOT_CONFIGURED",400);String key=vault.load(user,id,p).orElseThrow(ProviderKeyMissingException::new);return new ProviderSession(p,key,registry.require(p.getProtocol()));}
 public ProviderAdapter adapterFor(AiProviderConfig provider){return registry.require(provider.getProtocol());}
 public ProviderResponse complete(long user,ProviderCapability capability,String system,String prompt){ProviderSession s=require(user,capability);AiRoutingConfig r=routing.selectOwned(user);return s.getAdapter().complete(s.getProvider(),s.getApiKey(),new TextCompletionRequest(system,prompt,r.getMaxOutputTokens()));}}
